// apps/cli/src/templates/fly-toml.ts

/**
 * Generate a fly.toml for Fly.io deployment.
 *
 * `mode: "daemon"` (default) runs the always-on gateway (cron, heartbeat, channels), so
 * machines must never auto-stop. `mode: "sdk"` is request-driven and may scale to zero.
 * Exactly one health check is defined (`[[http_service.checks]]`).
 */
export const flyTomlTemplate = (
  agentName: string,
  isMonorepo: boolean,
  appPath?: string,
  mode: "daemon" | "sdk" = "daemon",
) => `# Fly.io configuration for raxd agent
# Generated by: rax deploy up --target fly
# Docs: https://fly.io/docs/reference/configuration/

app = "raxd-${agentName}"
primary_region = "iad"

[build]
${isMonorepo ? `  dockerfile = "${appPath}/Dockerfile"` : "  dockerfile = \"Dockerfile\""}

[env]
  HEALTH_PORT = "3000"

[http_service]
  internal_port = 3000
  force_https = true
${mode === "daemon"
  ? `  # Daemon mode: cron + heartbeat must keep running, so never stop the machine.
  auto_stop_machines = "off"
  auto_start_machines = true
  min_machines_running = 1`
  : `  # SDK mode: request-driven, may scale to zero.
  auto_stop_machines = "stop"
  auto_start_machines = true
  min_machines_running = 0`}

  [http_service.concurrency]
    type = "connections"
    hard_limit = 25
    soft_limit = 20

  [[http_service.checks]]
    grace_period = "10s"
    interval = "30s"
    method = "GET"
    path = "/health"
    timeout = "5s"

[[vm]]
  size = "shared-cpu-1x"
  memory = "512mb"
`;

/** Generate a fly.io Dockerfile (wraps existing Dockerfile for context) */
export const flyDockerfileNote = () =>
  "# Your existing Dockerfile works with Fly.io — no changes needed.\n" +
  "# Fly.io will use the Dockerfile specified in fly.toml.\n";
